<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useWorkspace} from '../workspace';
import type {QuestionAnswer,QuestionSet} from '../controller';
import {containsCredential} from '../credential-warning';
const props=defineProps<{request:QuestionSet}>();
const {app,state}=useWorkspace();
const agent=computed(()=>state.value.bots.find(bot=>bot.id===props.request.botId)?.name ?? 'Agent');
const copy=(values:QuestionAnswer[]):QuestionAnswer[]=>values.map(value=>value ? {choices:[...value.choices],writeIn:value.writeIn} : null);
const gmailPreview=ref<Awaited<ReturnType<typeof app.gmailSetupPreview>>|null>(null),gmailUrl=ref('');
const initialQuestion=props.request.questions[0];
const secretName=ref(initialQuestion?.kind==='secret'?initialQuestion.name:'');
const secretValue=ref(''),reveal=ref(false),selected=ref(''),secrets=ref<Awaited<ReturnType<typeof app.secrets>>>([]);
onMounted(async()=>{try{secrets.value=await app.secrets();if(props.request.gmailSetup==='authorizing')gmailUrl.value=(await app.gmailSetupAuthorization(props.request.id)).url;}catch{error.value='Could not load secret or authorization details.';}});
const index=ref(0),answers=ref<QuestionAnswer[]>(copy(props.request.draft)),busy=ref(false),error=ref('');
let timer:ReturnType<typeof setTimeout>|undefined;
let writes=Promise.resolve();
const current=computed(()=>props.request.questions[index.value]);
const hasCredential=computed(()=>answers.value.some(value=>value && containsCredential(value.writeIn)));
function recordedSecretStatus(i:number){const result=props.request.result;if(result && typeof result==='object' && 'answers' in result && Array.isArray(result.answers)){const item=result.answers[i];if(item && typeof item==='object' && 'status' in item && typeof item.status==='string')return item.status;}return props.request.secretStatuses[i];}
function answer(i:number){return answers.value[i] ?? {choices:[],writeIn:''};}
function update(i:number,value:Exclude<QuestionAnswer,null>) {answers.value[i]=value;queue();}
function writeIn(i:number,value:string){const old=answer(i);update(i,{...old,writeIn:value,...(props.request.questions[i]?.kind==='single' && value.trim()?{choices:[]}: {})});}
function select(i:number,choice:string,checked:boolean){const old=answer(i),question=props.request.questions[i];const choices=question?.kind==='single'?[choice]:checked?[...old.choices,choice]:old.choices.filter(c=>c!==choice);update(i,{choices,writeIn:question?.kind==='single'?'':old.writeIn});}
function queue(){if(timer)clearTimeout(timer);timer=setTimeout(()=>{void save().catch(()=>{});},300);}
function save(){if(timer)clearTimeout(timer);timer=undefined;const snapshot=copy(answers.value).map(value=>value && containsCredential(value.writeIn)?{...value,writeIn:''}:value);writes=writes.catch(()=>{}).then(()=>app.questionDraft(props.request.id,snapshot)).then(()=>{error.value='';});return writes.catch(e=>{error.value=String(e);throw e;});}
async function finish(kind:'submit'|'dismiss'){if(kind==='submit' && hasCredential.value)return;busy.value=true;error.value='';try{if(kind==='submit')await save();else {if(timer)clearTimeout(timer);await writes;}await app.questionFinish(props.request.id,kind);}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function saveSecret(operation:'save'|'select'){const secret=secrets.value.find(item=>item.name===selected.value);if(operation==='select' && !secret)return;busy.value=true;error.value='';try{if(operation==='save')await app.questionSecret(props.request.id,index.value,'save',{value:secretValue.value,name:secretName.value});else if(secret)await app.questionSecret(props.request.id,index.value,'select',{name:secret.name,revision:secret.revision});secretValue.value='';reveal.value=false;secrets.value=await app.secrets();}catch{error.value='Could not save the secret. Check the request and try again.';}finally{busy.value=false;}}
async function reviewGmail(){busy.value=true;error.value='';try{await save();gmailPreview.value=await app.gmailSetupPreview(props.request.id);}catch{error.value='Complete the Gmail address, client ID and protected secret, then review again.';}finally{busy.value=false;}}
async function startGmail(){const reviewed=gmailPreview.value;if(!reviewed)return;const replacesClient=!!reviewed.clientTarget.current && (reviewed.clientTarget.current.name!==reviewed.secret.name || reviewed.clientTarget.current.revision!==reviewed.secret.revision);const replacesRefresh=!!reviewed.refreshTarget.current;busy.value=true;error.value='';try{const result=await app.gmailSetupStart(props.request.id,reviewed,replacesClient || replacesRefresh);gmailUrl.value=result.url;gmailPreview.value=null;}catch{gmailPreview.value=null;error.value='Gmail setup could not start. A use approval may have been saved; review the current details and approvals before trying again.';}finally{busy.value=false;}}
function navigate(i:number){secretValue.value='';reveal.value=false;selected.value='';index.value=i;const question=props.request.questions[i];secretName.value=question?.kind==='secret'?question.name:'';void save().catch(()=>{});}
watch(()=>props.request.gmailSetup,async status=>{if(status==='authorizing'){try{gmailUrl.value=(await app.gmailSetupAuthorization(props.request.id)).url;}catch{gmailUrl.value='';}}else gmailUrl.value='';});
watch(()=>props.request.id,()=>{answers.value=copy(props.request.draft);index.value=0;});
watch(()=>props.request.state, state=>{if(state!=='open'){if(timer)clearTimeout(timer);secretValue.value='';reveal.value=false;answers.value=copy(props.request.draft);}});
</script>
<template>
 <section class="question-set" :aria-label="'Question set for this response'">
  <template v-if="request.state==='open'">
   <p v-if="request.originState==='interrupted' || request.originState==='failed' || request.originState==='stopped'" role="status">{{ request.workKind==='task' ? 'The task was interrupted. Your answers will be saved, but the task will not resume automatically. Review the work before starting a new attempt.' : 'The original response was interrupted. Your answers will be saved, but it will not resume automatically. Review the work and send a new message when you are ready.' }}</p>
   <div v-if="request.gmailSetup" class="item" aria-label="Gmail setup">
    <p>Gmail setup: {{ request.gmailSetup }}.</p>
    <p v-if="request.gmailSetup==='connected'">Google authorization and the Gmail account check succeeded. Submit the answers to tell the agent.</p>
    <p v-else-if="request.gmailSetup==='authorizing'">Google authorization is pending. Submitting or dismissing now interrupts this attempt.</p>
    <p v-else-if="request.gmailSetup==='interrupted'">The authorization was interrupted. Check Gmail status and saved use approvals before starting a new attempt.</p>
    <p v-else-if="request.gmailSetup==='failed'">The connection failed or is no longer available. Some credentials or use approvals may have been saved; review them and the Gmail status before trying again.</p>
    <a v-if="gmailUrl && request.gmailSetup==='authorizing'" :href="gmailUrl" target="_blank" rel="noopener noreferrer">Open Google authorization</a>
    <button v-if="request.gmailSetup!=='authorizing' && request.gmailSetup!=='connected' && !gmailPreview" type="button" :disabled="busy" @click="reviewGmail">Review Gmail connection</button>
    <button type="button" class="quiet" :disabled="busy" @click="app.refresh()">Refresh Gmail status</button>
    <div v-if="gmailPreview"><p>Connect {{ gmailPreview.email }} using client ID {{ gmailPreview.clientId }} and secret {{ gmailPreview.secret.name }} to Google's OAuth token endpoint and Gmail API.</p><p>Google permissions: Gmail read access<span v-if="gmailPreview.sendEnabled">, send replies</span><span v-if="gmailPreview.modifyEnabled">, inbox changes</span>. Agent access and model permissions remain separate.</p><p v-if="gmailPreview.clientTarget.current && (gmailPreview.clientTarget.current.name!==gmailPreview.secret.name || gmailPreview.clientTarget.current.revision!==gmailPreview.secret.revision)">This replaces the Gmail client approval for {{ gmailPreview.clientTarget.current.name }} at this destination.</p><p v-if="gmailPreview.refreshTarget.current">This replaces the Gmail refresh-token approval for {{ gmailPreview.refreshTarget.current.name }} at this destination.</p><button type="button" :disabled="busy" @click="startGmail">Confirm and continue to Google</button><button type="button" class="quiet" :disabled="busy" @click="gmailPreview=null">Back</button></div>
   </div>
   <nav aria-label="Questions"><button v-for="(question,i) in request.questions" :key="i" type="button" class="quiet" :disabled="busy" :aria-current="i===index?'step':undefined" @click="navigate(i)">Question {{ i+1 }}<span v-if="question.kind==='secret' ? request.secretStatuses[i]!=='saved' : !answer(i).choices.length && !answer(i).writeIn.trim()"> · unanswered</span></button></nav>
   <fieldset v-if="current" :disabled="busy || request.gmailSetup==='connected'"><legend>Question {{ index+1 }} of {{ request.questions.length }}: {{ current.prompt }}</legend>
    <template v-if="current.kind==='single' || current.kind==='multiple'"><label v-for="choice in current.choices" :key="choice"><input :type="current.kind==='single'?'radio':'checkbox'" :name="request.id+'-'+index" :checked="answer(index).choices.includes(choice)" @change="select(index,choice,($event.target as HTMLInputElement).checked)"> {{ choice }}</label></template>
    <template v-if="current.kind==='secret'"><p>{{ agent }} requests {{ current.name }} — {{ current.purpose }}</p><p v-if="current.destination">Intended destination: {{ current.destination }}</p><p>Saving does not authorize use. Saved values cannot be revealed.</p><template v-if="request.secretStatuses[index]!=='saved'"><p v-if="request.secretStatuses[index]==='unavailable'" role="status">The selected secret changed or was deleted. Select or save a secret again.</p><label v-if="secrets.length">Existing secret <select v-model="selected"><option value="">Choose a secret</option><option v-for="secret in secrets" :key="secret.name" :value="secret.name">{{ secret.name }}</option></select></label><button v-if="secrets.length" type="button" :disabled="!selected" @click="saveSecret('select')">Select secret</button><label>Name <input v-model="secretName" maxlength="120"></label><label>Secret <input v-model="secretValue" :type="reveal?'text':'password'" autocomplete="off"></label><button type="button" class="quiet" @click="reveal=!reveal">{{ reveal?'Hide':'Reveal' }}</button><button type="button" :disabled="!secretValue || !secretName.trim()" @click="saveSecret('save')">Save secret</button></template><p v-else>Saved secret: {{ request.secretSelections[index]?.name }}</p></template>
    <label v-if="current.kind!=='secret'" :for="request.id+'-write'">{{ current.kind==='text'?'Your answer':'Your own answer' }} (optional)</label><textarea v-if="current.kind!=='secret'" :id="request.id+'-write'" :value="answer(index).writeIn" @input="writeIn(index,($event.target as HTMLTextAreaElement).value)" />
   </fieldset>
   <button v-if="current?.kind!=='secret' && request.gmailSetup!=='connected'" type="button" class="quiet" :disabled="busy" @click="update(index,{choices:[],writeIn:''})">Skip this question</button>
   <p>Every question is optional. Unanswered questions will be sent as skipped.</p>
   <p v-if="hasCredential" role="alert">An answer looks like it contains a credential. It is not saved or submitted. Remove it or skip that answer, then ask the agent in chat to request it through protected secret entry, or use the relevant connection in Settings. Detection is incomplete.</p>
   <button v-if="index>0" :disabled="busy" type="button" class="quiet" @click="navigate(index-1)">Back</button><button v-if="index<request.questions.length-1" :disabled="busy" type="button" class="quiet" @click="navigate(index+1)">Next</button>
   <button type="button" :disabled="busy" @click="finish('submit')">Submit answers</button><button type="button" class="quiet" :disabled="busy" @click="finish('dismiss')">Dismiss</button><p v-if="error" role="alert">{{ error }}</p>
  </template>
  <template v-else><p>Question set {{ request.state }}.</p><ol v-if="request.state==='submitted'"><li v-for="(question,i) in request.questions" :key="i">{{ question.prompt }}: {{ question.kind==='secret' ? recordedSecretStatus(i) : [...answer(i).choices, ...(answer(i).writeIn.trim() ? [answer(i).writeIn] : [])].join(', ') || 'Skipped' }}</li></ol><template v-if="request.workKind==='task'"><p v-if="['failed','stopped','interrupted'].includes(request.originState)">The task {{ request.originState }} and will not resume automatically. Review its prior work before starting a new attempt.</p><p v-else-if="request.originState==='running'">The response is available to this task.</p></template><template v-else><p v-if="request.originState==='pending'">Waiting for the original response to finish.</p><p v-else-if="request.originState!=='completed'">The original response {{ request.originState }}; no automatic continuation was started. Review the work and send a new message to try again.</p><p v-else-if="request.deliveryError" role="status">{{ request.deliveryError }}</p><p v-else-if="!request.continuationState">Waiting to deliver your response.</p><p v-else-if="request.continuationState==='interrupted' || request.continuationState==='failed'">The follow-up {{ request.continuationState }}. Review the conversation before trying again.</p></template></template>
 </section>
</template>
